import { Injectable } from '@angular/core';
import { BetTeamAddRequest, BetTeamAddRequestResult, Item, MultiSelection, Selection } from './advanced-mode.model';
import { MultipleSelection } from '../../multiple-selection/multiple-selection.model';
import { AdvancedModeConstants } from '../../advanced-mode/advanced-mode.constants';
import { MultipleSelectionService } from '../../multiple-selection/multiple-selection.service';
import { ItemsSelectService } from '../../multiple-selection/items-select.service';

@Injectable({
  providedIn: 'root'
})
export class BetTeamAddRequestService {
  constructor(private readonly multipleSelectionService: MultipleSelectionService) {}
  
  private renderSelections(betTeam: BetTeamAddRequest, selections: Selection[]) {
    betTeam.selections = [];
    if (selections !== null) {
      this.renderValidSelection(betTeam, selections);
    }
  }

  private renderValidSelection(betTeam: BetTeamAddRequest, selections: Selection[]) {
    for (const [index, item] of selections.entries()) {
      if (item.isMultiple) {
        item.index = index;
        item.multiSelection = this.renderMultipleSelection(item);
        betTeam.selections.push(item);
      } else {
        const selection = this.initSelectionAdvancedMode(index, item.name, item.value, item.items, item.isMultiple, item.xmlAttribute);
        betTeam.selections.push(selection);
      }
    }
  }

  renderMultipleSelection(item: Selection): MultiSelection {
    const model = new MultiSelection();
    model.multipleSelect = new MultipleSelection();
    model.multipleSelect.checkAllCheckBoxText = 'All';
    model.multipleSelect.allItemsCheckedText = 'All';
    model.multipleSelect.noneItemCheckedText = 'Select options';
    model.multipleSelect.maxWidth = '100%';
    this.renderItemsMultipleSelection(item, model);

    return model;
  }

  private renderItemsMultipleSelection(multi: Selection, model: MultiSelection) {
    model.name = multi.name;
    model.value = multi.value;
    model.xmlAttribute = multi.xmlAttribute;
    model.multipleSelect.items.length = 0;
    multi.items?.forEach(item => {
      const temp = [];
      if (item.items !== null && item.items !== undefined) {
        item.items.forEach(itemSelect => {
          temp.push(ItemsSelectService.initItemsSelect(0, itemSelect.value, itemSelect.name, true, true, true, []));
        });
      }
      model.multipleSelect.items.push(ItemsSelectService.initItemsSelect(0, item.value, item.name, true, true, true, temp));
    });
    model.multipleSelect.isCheckAll = model.multipleSelect.items.every(x => x.checked);
    model.multipleSelect.selectionTitle = this.multipleSelectionService.getDisplayedItems(model.multipleSelect);
  }

  private renderInputs(betTeam: BetTeamAddRequest, inputs: Item[]) {
    betTeam.inputs = [];
    if (inputs !== null) {
      for (const [index, input] of inputs.entries()) {
        const temp = new Item(index, input.name, input.value, input.isRowSpan, input.isDisabled, input.isMultiple, input.xmlAttribute, input.format, false);
        betTeam.inputs.push(temp);
      }
    }
  }

  resetAllChecked(betTeam: BetTeamAddRequest){
    betTeam.selections.forEach(selection => {
      if (selection.multiSelection?.multipleSelect) {
        this.resetAllCheckedMultipleSelect(selection.multiSelection.multipleSelect);
      }
    });
  }

  getResult(betTeam: BetTeamAddRequest, betTypeId: string): BetTeamAddRequestResult {
    const result = new BetTeamAddRequestResult();
    this.updateBySelection(betTeam, result);
    this.updateByInputs(betTeam, result);
    this.updateBetTypeHalfFullTimeCorrectScore(betTeam.selections, result, betTypeId)
    this.updateForPenaltyShootoutCombo376(result, betTypeId);
    this.updateForBetTypesCricketWithFancy(result, betTypeId);
    this.updateForBetTypesWithRuns(result, betTypeId);
    result.id = betTypeId;

    return result;
  }

  private updateBySelection(betTeam: BetTeamAddRequest, result: BetTeamAddRequestResult) {
    betTeam.selections.forEach(selection => {
      const value = selection.isMultiple && selection.multiSelection?.multipleSelect
        ?  this.multipleSelectionService.getValueItems(selection.multiSelection.multipleSelect)
        : selection.value;
      this.updateResult(result, selection.xmlAttribute, value);
    });
  }

  private updateByInputs(betTeam: BetTeamAddRequest, result: BetTeamAddRequestResult) {
    if (betTeam.inputs.length > 0) {
      betTeam.inputs.forEach(input => {
        this.updateResult(result, input.xmlAttribute, input.value ?? '');
      });
    }
  }

  private updateResult(result: BetTeamAddRequestResult, attribute: string, value: string) { // NOSONAR
    switch (attribute.toLowerCase()) {
      case 'team':
        result.team = value;
        break;
      case 'hdp':
      case 'hdp1':
      case 'hdp2':
        result.hdp = value;
        break;
      case 'player':
        result.player = value;
        break;
      case 'playerandodds':
        result.playerAndOdds = value;
        break;
      case 'oddsspread':
        result.oddsSpread = value;
        break;
      case '_xx': // use for input: XX value & selections round: XX in betid type 8XX; link to column betId
        result.betIdX = value;
        result.filterBetIdX = this.getValueBetIdTypeXx(value);
        break;
      case '_xxx': // use for input: XXX value in betid type 8XXX, 8XXXYY; link to column betId
        result.betIdX = value;
        result.filterBetIdX = this.getValueBetIdTypeXxx(value); // value = 1 => _001; value = 11 => _011; value = 1111 => _1111
        break;
      case 'yy': // use for input: YY value in betid type (8XXYY, 8XXXYY); link to column betId
        result.betIdY = value;
        result.filterBetIdY = this.getValueBetIdTypeYy(value); // value = 1 => 01; value = 11 => 11; value = 111 => 111
        break;
      case 'betidx': // use for selection: value is configured in the json file; link to column betId
        result.betIdX = value;
        result.filterBetIdX = value;
        break;
      case 'betidy': // use for selection: value is configured in the json file; link to column betId
        result.betIdY = value;
        result.filterBetIdY = value;
        break;
      case 'firstvalue':
        result.firstValue = value;
        break;
      case 'secondvalue':
        result.secondValue = value;
        break;
      case 'performance':
        result.performance = value;
        break;
    }
  }

  private getValueBetIdTypeXx(value: string): string {
    if (!value) {
      return '___';
    }

    const newValue = value.replaceAll(',','&'); //replace values selection

    return newValue.split('&')
      .filter(Boolean)
      .map(x => `_${x.padStart(2, '0')}`)
      .join('&');
  }

  private getValueBetIdTypeXxx(value: string): string {
    if (!value) {
      return '____';
    }

    return value.split('&')
      .filter(Boolean)
      .map(x => `_${x.padStart(3, '0')}`)
      .join('&');
  }

  private getValueBetIdTypeYy(value: string): string {
    if (!value) {
      return '';
    }

    return value.split('&')
      .filter(Boolean)
      .map(y => y ? y.padStart(2, '0') : '__')
      .join('&');
  }

  private updateBetTypeHalfFullTimeCorrectScore(selections: Selection[], result: BetTeamAddRequestResult, betTypeId: string): void {
    if (this.isHalfFullTimeCorrectScoreBet(betTypeId)) {
      const [selection1, selection2] = selections;
      const team = this.getCombinedSelectionValueBetTypeFullTimeCorrectScore(selection1, selection2);
      result.team = team;
    }
  }

  private isHalfFullTimeCorrectScoreBet(betTypeId: string) {
    return [
      AdvancedModeConstants.BETTYPE_HALF_FULL_TIME_CORRECT_SCORE,
      AdvancedModeConstants.BETTYPE_HALF_FULL_TIME_CORRECT_SCORE_AOS,
    ].includes(betTypeId);
  }

  private getCombinedSelectionValueBetTypeFullTimeCorrectScore(selection1: Selection, selection2: Selection) {
    if (selection1.value?.toLowerCase() === 'all' && selection2.value?.toLowerCase() === 'all') {
      return 'All';
    }
    if (selection1.value?.toLowerCase() === 'all') {
      return selection1.items.slice(1).map(item1 => `${item1.value}/${selection2.value}`).join(',');
    }
    if (selection2.value?.toLowerCase() === 'all') {
      return selection2.items.slice(1).map(item2 => `${selection1.value}/${item2.value}`).join(',');
    }

    return `${selection1.value}/${selection2.value}`;
  }

  private updateForPenaltyShootoutCombo376(result: BetTeamAddRequestResult, betTypeId: string): void {
    if (betTypeId === AdvancedModeConstants.BETTYPE_PENALTY_SHOOTOUT_COMBO) {
      result.team = `${result.firstValue}-${result.secondValue}`;
    }
  }

  private updateForBetTypesCricketWithFancy(result: BetTeamAddRequestResult, betTypeId: string): void {
    if (AdvancedModeConstants.BETTYPES_CRICKET_UPDATE_FANCY.split(',').includes(betTypeId)) {
      if (result.team?.toLowerCase() === 'all') {
        result.hdp = result.firstValue;
      } else if(result.team?.toLowerCase() === 'n') {
        result.hdp1 = result.firstValue;
      } else if (result.team?.toLowerCase() === 'y') {
        result.hdp2 = result.firstValue;
      }
    }
  }

  private updateForBetTypesWithRuns(result: BetTeamAddRequestResult, betTypeId: string): void {
    if (AdvancedModeConstants.BETTYPE_OVER_X_EXACT_RUNS.split(',').includes(betTypeId)) {
      const runesTransform = AdvancedModeConstants.RUNS_SELECTION.find(x => x.value === result.firstValue);
      result.team = runesTransform.betTeam;
      result.hdp1 = runesTransform.valueHdp1;
    }
  }

  updateItemChecked(multipleSelect: MultipleSelection, checkedItems: string[]) {
    this.multipleSelectionService.updateItemChecked(multipleSelect, checkedItems);
  }

  private resetAllCheckedMultipleSelect(multipleSelect: MultipleSelection) {
    this.multipleSelectionService.checkAllItems(multipleSelect, true);
    multipleSelect.isCheckAll = true;
  }

  updateDisabledStatus(multipleSelect: MultipleSelection, isDisabled: boolean) {
    multipleSelect.items.forEach(item => item.enable = !isDisabled);
    multipleSelect.isDisabled = isDisabled;
  }

  initBetTeamAddRequest( commonInfo: [number, string, string, number, string], selections: Selection[], inputs: Item[], isChecked: boolean) {
    const betTeam = new BetTeamAddRequest();
    betTeam.index = commonInfo[0];
    betTeam.name = commonInfo[1];
    betTeam.value = commonInfo[2];
    betTeam.type = commonInfo[3];
    betTeam.betTypes = commonInfo[4];
    this.renderSelections(betTeam, selections);
    this.renderInputs(betTeam, inputs);
    betTeam.isShow = isChecked;

    return betTeam;
  }

  private renderItems(selection: Selection, items: Selection[]) {
    selection.items = [];
    if (items !== null) {
      for (const [index, item] of items.entries()) {
        const temp = this.initSelectionAdvancedMode(index, item.name, item.value, item.items, item.isMultiple, item.xmlAttribute);
        selection.items.push(temp);
      }
    }
  }

  initSelectionAdvancedMode(index: number, name: string, value: string, items: Selection[], isMultiple: boolean, xmlAttribute: string) {
    const selection = new Selection();
    selection.index = index;
    selection.name = name;
    selection.value = value;
    this.renderItems(selection, items);
    selection.isMultiple = isMultiple;
    selection.xmlAttribute = xmlAttribute;

    return selection;
  }
}
